<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Notifications;use Acorn\SafetyHealthcheck\Assessment\{AssessmentRepository,ContactRepository};use Acorn\SafetyHealthcheck\Reports\{ReportDataBuilder,PdfGenerator};final class CustomerMailer{public function send(int$id):bool{$a=(new AssessmentRepository)->find($id);$c=(new ContactRepository)->find((int)$a['contact_id']);$data=(new ReportDataBuilder)->build($id);$url=home_url('/healthcheck/report/');$subject=get_option('acorn_hc_settings')['customer_email_subject']??'Your Acorn Health & Safety Healthcheck';$body="Your result: {$data['summary']['priority_count']} priority actions and {$data['summary']['review_count']} areas to review.\n$url";return wp_mail($c['email'],$subject,$body);}}
